diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..3589045 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,51 @@ export interface Record {
   warns: readonly string[];
 }

+const canonicalizeConstraint = (text: string): string => {
+  const normalized = text.toLowerCase();
+
+  if (
+    normalized.includes("operational") ||
+    normalized.includes("stateful service") ||
+    normalized.includes("always-on") ||
+    normalized.includes("someone has to operate") ||
+    normalized.includes("one more thing to run")
+  ) {
+    return "infrastructure requires operational overhead";
+  }
+
+  return text;
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
+  const seen = new Set<string>();
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) {
+      const canonical = canonicalizeConstraint(entry);
+      const key = `ruled out: ${canonical}`;
+      if (!seen.has(key)) {
+        lines.push(`- ${key}`);
+        seen.add(key);
+      }
+    }
+    for (const limit of record.limits) {
+      const canonical = canonicalizeConstraint(limit);
+      const key = `limit: ${canonical}`;
+      if (!seen.has(key)) {
+        lines.push(`- ${key}`);
+        seen.add(key);
+      }
+    }
+    for (const warn of record.warns) {
+      const canonical = canonicalizeConstraint(warn);
+      const key = `warn: ${canonical}`;
+      if (!seen.has(key)) {
+        lines.push(`- ${key}`);
+        seen.add(key);
+      }
+    }
   }
   return lines.join("\n");
 };
